(()=>{'use strict';const days=[['ش',6,'شنبه'],['ی',0,'یکشنبه'],['د',1,'دوشنبه'],['س',2,'سه‌شنبه'],['چ',3,'چهارشنبه'],['پ',4,'پنجشنبه'],['ج',5,'جمعه']],$=s=>document.querySelector(s),clean=v=>String(v||'').trim(),clock=v=>String(v||'').slice(0,5),dayText=r=>days.filter(([,v])=>(r.weekdays||[]).map(Number).includes(v)).map(([, ,n])=>n).join('، '),current=()=>typeof session!=='undefined'&&session?.user&&typeof mine==='function'&&mine()?session.user:null;
async function list(){const user=current();if(!user)throw Error('برای تنظیم یادآور وارد شوید.');const {data,error}=await db.from('sm_routine_alarms').select('*').eq('user_id',user.id).order('remind_at');if(error)throw error;return data||[]}
function head(){return modalHead('یادآورهای من')+'<section class="routine-reminders"><p class="routine-intro">برای خودتان یادآور زمان‌دار بسازید؛ روزهای دلخواه را انتخاب کنید تا در همان ساعت، اعلان دستگاه دریافت کنید.</p><div class="routine-toolbar"><button class="primary" type="button" id="routineAdd">＋ یادآور جدید</button><small>اعلان این دستگاه را از بخش «اعلان‌های این دستگاه» فعال کنید.</small></div><div id="routineList" class="routine-list" aria-live="polite"></div></section>'}
function form(r={active:true,weekdays:[6,0,1,2,3,4,5],remind_at:'08:00'}){const chosen=(r.weekdays||[]).map(Number);return `<section class="routine-editor"><button type="button" class="routine-back" id="routineBack">← بازگشت به یادآورها</button><h3>${r.id?'ویرایش یادآور':'یادآور جدید'}</h3><form id="routineForm"><label>عنوان یادآور<input name="title" maxlength="160" required placeholder="مثلاً ارسال گزارش روزانه" value="${esc(r.title||'')}"></label><label>توضیح کوتاه <small>(اختیاری)</small><input name="note" maxlength="800" placeholder="یک توضیح کوتاه" value="${esc(r.note||'')}"></label><div class="routine-time-row"><label>ساعت<input name="remind_at" type="time" required value="${clock(r.remind_at)||'08:00'}"></label><label class="routine-active"><input name="active" type="checkbox" ${r.active!==false?'checked':''}><span>یادآور فعال باشد</span></label></div><fieldset><legend>روزهای تکرار</legend><div class="routine-day-picker">${days.map(([s,v,n])=>`<label title="${n}"><input type="checkbox" name="weekdays" value="${v}" ${chosen.includes(v)?'checked':''}><span>${s}</span></label>`).join('')}</div></fieldset><div class="routine-form-actions">${r.id?'<button class="danger" type="button" id="routineDelete">حذف یادآور</button>':''}<button class="primary" type="submit">ذخیره یادآور</button></div></form></section>`}
async function renderList(){const box=$('#routineList');if(!box)return;box.innerHTML='<div class="routine-loading">در حال دریافت یادآورها…</div>';try{const rows=await list();box.innerHTML=rows.length?rows.map(r=>`<article class="routine-item ${r.active?'':'is-off'}"><button class="routine-toggle" type="button" data-toggle="${r.id}" aria-pressed="${r.active}">${r.active?'فعال':'خاموش'}</button><button class="routine-main" type="button" data-edit="${r.id}"><strong>${esc(r.title)}</strong>${r.note?`<small>${esc(r.note)}</small>`:''}<span>${clock(r.remind_at)} · ${dayText(r)}</span></button></article>`).join(''):'<div class="routine-empty"><b>هنوز یادآوری ندارید.</b><span>یک روتین شخصی بسازید تا در ساعت و روز دلخواهتان یادتان بیندازد.</span></div>';box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.edit)));box.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{const r=rows.find(x=>x.id===b.dataset.toggle);b.disabled=true;const {error}=await db.from('sm_routine_alarms').update({active:!r.active,updated_at:new Date().toISOString()}).eq('id',r.id);if(error)message('تغییر ذخیره نشد.');await renderList()})}catch{box.innerHTML='<div class="routine-empty">دریافت یادآورها ممکن نشد. دوباره تلاش کنید.</div>'}}
function edit(row={active:true,weekdays:[6,0,1,2,3,4,5],remind_at:'08:00'}){$('#sharedDetail').innerHTML=modalHead(row.id?'ویرایش یادآور':'یادآور جدید')+form(row);$('#sharedClose').onclick=()=>$('#sharedDialog').close();$('#routineBack').onclick=open;const f=$('#routineForm');f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type="submit"]'),v=new FormData(f),weekdays=[...f.querySelectorAll('[name="weekdays"]:checked')].map(x=>Number(x.value));if(!weekdays.length)return message('حداقل یک روز را انتخاب کنید.');button.disabled=true;const payload={user_id:current().id,title:clean(v.get('title')),note:clean(v.get('note')),remind_at:v.get('remind_at'),weekdays,active:f.active.checked,updated_at:new Date().toISOString()};if(row.id)payload.id=row.id;const {error}=await db.from('sm_routine_alarms').upsert(payload);if(error){message('ذخیره یادآور انجام نشد.');button.disabled=false;return}message('یادآور ذخیره شد.');open()};const del=$('#routineDelete');if(del)del.onclick=async()=>{if(!confirm('این یادآور حذف شود؟'))return;del.disabled=true;const {error}=await db.from('sm_routine_alarms').delete().eq('id',row.id);if(error){message('حذف انجام نشد.');del.disabled=false;return}message('یادآور حذف شد.');open()}}
function open(){if(!current())return message('اول وارد حساب خودتان شوید.');modal(head());$('#routineAdd').onclick=()=>edit();renderList()}
function menu(){const panel=$('#accountMorePanel');if(!panel||$('#routineMenuButton'))return;const b=document.createElement('button');b.type='button';b.id='routineMenuButton';b.className='account-settings-link routine-menu-link';b.textContent='یادآورهای من';b.onclick=()=>{panel.hidden=true;open()};panel.insertBefore(b,panel.querySelector('.account-trash-link')||null)}new MutationObserver(menu).observe(document.body,{childList:true,subtree:true});menu();window.SamandisOpenRoutines=open;if(new URL(location.href).searchParams.get('routine'))setTimeout(open,600)})();
